// Converte posicao da CENA (mundo) para celula da grade. Retorna false se fora.
static inline bool island_cell_from_scene(
    float scene_x, float scene_z,
    float island_x, float island_z, float island_scale,
    int &cell_x, int &cell_z)
{
    const float local_x = (scene_x - island_x) / island_scale;
    const float local_z = (scene_z - island_z) / island_scale;

    cell_x = static_cast<int>(std::floor((local_x - kIslandGridX0) / kIslandGridCell));
    cell_z = static_cast<int>(std::floor((local_z - kIslandGridZ0) / kIslandGridCell));

    return cell_x >= 0 && cell_x < kIslandGridNX &&
           cell_z >= 0 && cell_z < kIslandGridNZ;
}

// true se a posicao (x, z) da cena e um lugar onde a pessoa pode ficar em pe.
static inline bool island_is_walkable(
    float scene_x, float scene_z,
    float island_x, float island_z, float island_scale)
{
    int cx = 0, cz = 0;

    if (!island_cell_from_scene(scene_x, scene_z, island_x, island_z, island_scale, cx, cz))
        return false;

    return kIslandWalkable[cz * kIslandGridNX + cx] != 0;
}

// Altura Y do chao (em unidades da CENA) com interpolacao bilinear.
static inline float island_ground_height(
    float scene_x, float scene_z,
    float island_x, float island_y, float island_z, float island_scale)
{
    const float local_x = (scene_x - island_x) / island_scale;
    const float local_z = (scene_z - island_z) / island_scale;

    const float fx = (local_x - kIslandGridX0) / kIslandGridCell - 0.5f;
    const float fz = (local_z - kIslandGridZ0) / kIslandGridCell - 0.5f;

    int x0 = static_cast<int>(std::floor(fx));
    int z0 = static_cast<int>(std::floor(fz));

    const float tx = fx - static_cast<float>(x0);
    const float tz = fz - static_cast<float>(z0);

    auto sample = [](int x, int z) -> float {
        if (x < 0) x = 0;
        if (x >= kIslandGridNX) x = kIslandGridNX - 1;
        if (z < 0) z = 0;
        if (z >= kIslandGridNZ) z = kIslandGridNZ - 1;
        return kIslandGroundMm[z * kIslandGridNX + x] * 0.001f;
    };

    const float h00 = sample(x0, z0);
    const float h10 = sample(x0 + 1, z0);
    const float h01 = sample(x0, z0 + 1);
    const float h11 = sample(x0 + 1, z0 + 1);

    const float h0 = h00 + (h10 - h00) * tx;
    const float h1 = h01 + (h11 - h01) * tx;
    const float local_y = h0 + (h1 - h0) * tz;

    return island_y + local_y * island_scale;
}

#endif // ISLAND_COLLISION_H
